public class BankAccountMain { public static void main(String[] args) { SavingsAccount a=new SavingsAccount(500); a.deposit(200); a.withdraw(650); a.withdraw(100); System.out.println("Balance: "+a.getBalance()); } }
class BankAccount { protected double balance; BankAccount(double balance){this.balance=Math.max(0,balance);} void deposit(double amount){if(amount>0) balance+=amount; else System.out.println("Deposit must be positive.");} void withdraw(double amount){if(amount>0&&amount<=balance) balance-=amount; else System.out.println("Withdrawal rejected.");} double getBalance(){return balance;} }
class SavingsAccount extends BankAccount { SavingsAccount(double balance){super(balance);} @Override void withdraw(double amount){if(amount>0&&amount<=balance&&balance-amount>=100){balance-=amount;System.out.println("Withdrawal successful.");}else System.out.println("Rejected: balance cannot fall below Rs. 100.");} }
